$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if (!$id) { http_response_code(404); exit; }
$find = $pdo->prepare('SELECT * FROM summaries WHERE id=? LIMIT 1'); $find->execute([$id]); $summary = $find->fetch(); if (!$summary) { http_response_code(404); exit; }
function replace_summary_file(array $file): ?string { $allowed = ['application/pdf'=>'pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','image/jpeg'=>'jpg','image/png'=>'png']; if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK || ($file['size'] ?? 0) > 26214400) return null; $mime = (new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']); if (!isset($allowed[$mime])) return null; $name = bin2hex(random_bytes(16)).'.'.$allowed[$mime]; return move_uploaded_file($file['tmp_name'], __DIR__.'/uploads/'.$name) ? $name : null; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); if (isset($_POST['delete_summary'])) { $pdo->prepare('DELETE FROM summaries WHERE id=?')->execute([$id]); $oldPath = __DIR__.'/uploads/'.basename($summary['file_name']); if (is_file($oldPath)) unlink($oldPath); header('Location: summaries-admin.php'); exit; } $newFile = isset($_FILES['file']) && $_FILES['file']['error'] !== UPLOAD_ERR_NO_FILE ? replace_summary_file($_FILES['file']) : null; $values = [trim($_POST['title'] ?? ''),trim($_POST['subject'] ?? ''),trim($_POST['grade'] ?? ''),trim($_POST['description'] ?? '')]; if ($newFile !== null) { $pdo->prepare('UPDATE summaries SET title=?,subject=?,grade=?,description=?,file_name=? WHERE id=?')->execute([...$values,$newFile,$id]); $oldPath = __DIR__.'/uploads/'.basename($summary['file_name']); if (is_file($oldPath)) unlink($oldPath); } else $pdo->prepare('UPDATE summaries SET title=?,subject=?,grade=?,description=? WHERE id=?')->execute([...$values,$id]); header('Location: summaries-admin.php'); exit; }
